// Original Years 7–8 practice and deterministic numerical variations.
// Arrays append to preserve every existing saved question key and friend link.
const CURRICULUM_REFERENCE={label:'ACARA · Years 7 and 8 learning overview',url:'https://www.australiancurriculum.edu.au/help/parent-information/what-students-learn-during-the-first-11-years-of-school',checked:'10 November 2026'};
function secondaryQuestion(id,year,prompt,answers,explanation,family='secondary-concept',tier=year===7?4:7){if(answers.length!==4||new Set(answers.map(String)).size!==4)throw Error('Invalid secondary options: '+prompt);BANK[id].push([prompt,answers.map(String),0,explanation,null,null,family,tier,year])}
const SECONDARY_CONCEPTS=[
['english',7,'Which revision uses nominalisation to create a more formal tone?','The investigation revealed a pattern.','We looked and saw a pattern.','Hey, look at that pattern!','There was, like, a pattern.','Investigation turns the action investigate into a noun. It helps create an impersonal, formal style when it suits the purpose.'],
['english',8,'A narrator insists “I never make mistakes”, but the story shows them repeatedly blaming others. Which reading is best supported?','The narrator may be unreliable, so readers should compare claims with events.','Everything the narrator says must be true.','The story has no point of view.','The sentence proves every other character is wrong.','A gap between a narrator’s claims and the events can signal unreliability. The reader evaluates the evidence rather than accepting every claim.'],
['english',7,'Which pair of clauses forms a compound sentence?','The rain stopped, and the players returned.','Although the rain stopped.','After the players returned.','The players on the wet oval.','A compound sentence joins independent clauses. Both the rain stopped and the players returned can stand alone.'],
['english',8,'A speech calls a proposal “a bridge to opportunity”. How does this metaphor position the audience?','It encourages them to see the proposal as a pathway to positive possibilities.','It proves that a physical bridge is being built.','It supplies numerical evidence of success.','It removes every possible interpretation.','The metaphor frames the proposal positively by connecting it with access and progress. It is persuasive language rather than proof.'],
['science',7,'In a food web, which statement best describes a producer?','It makes organic food using an energy source, usually sunlight.','It must eat another animal to obtain food.','It creates energy from nothing.','It has no connection to consumers.','Photosynthetic producers use light energy to build organic substances. They support food webs without creating energy from nothing.'],
['science',8,'Which statement correctly describes energy in a working electric fan?','Energy is transferred into movement and also dispersed as heat and sound.','The fan creates energy whenever its blades turn.','All input energy becomes useful movement.','Energy disappears when the fan stops.','Energy is conserved, but useful movement is only one output. Heat and sound transfer energy to the surroundings.'],
['biology',7,'A key separates animals into those with and without a backbone. Which feature should be examined next?','A further observable feature that divides the remaining group.','The animal’s popularity on social media.','A feature unrelated to identifying the animal.','The scientist’s favourite animal.','A classification key uses a sequence of observable distinctions. Each step narrows the possible identification.'],
['biology',8,'Which structure is present in plant cells but not animal cells?','A cellulose cell wall.','A cell membrane.','Cytoplasm.','Genetic material.','Plant cells have a cellulose cell wall outside their cell membrane. Both plant and animal cells contain a membrane, cytoplasm and genetic material.'],
['biology',8,'Why do multicellular organisms need specialised cells?','Different cell structures support different functions within the organism.','Every cell must perform exactly the same task.','Specialised cells no longer need energy.','Only single-celled organisms have cells.','Specialisation allows tasks such as transport, protection and movement to be performed efficiently by cells with suitable structures.'],
['chemistry',7,'A solution contains salt dissolved in water. Which method can recover solid salt?','Evaporate the water using suitable safe equipment.','Pass the solution through ordinary filter paper only.','Remove the salt with a magnet.','Add more water and expect the salt to become a solid immediately.','Dissolved salt passes through ordinary filter paper. Removing the water by evaporation can leave the salt behind.'],
['chemistry',8,'Which observation provides the strongest evidence that a new substance may have formed?','A gas is produced when two solutions are mixed and the change is reproducible.','A sheet of paper is folded in half.','Ice melts into liquid water.','A glass object is moved to another shelf.','Gas production can be evidence of a chemical reaction, although further evidence may be needed. Folding, melting and moving can occur without a new substance.'],
['chemistry',8,'Which description distinguishes a compound from a mixture?','A compound contains elements chemically combined in fixed proportions.','A compound is any collection of different objects.','A compound must always contain a metal.','A mixture always contains only one type of atom.','Compounds have chemically combined components and a fixed composition. Mixtures can contain substances in varying proportions without chemical bonding between them.'],
['history',7,'An ancient trade item is found far from where its material occurs naturally. What can this reasonably suggest?','People or goods may have moved between places, but other evidence is needed to reconstruct the route.','The exact route and date are proved by the item alone.','The item proves there was no contact between communities.','Every person in the region was a merchant.','Material origin can support an inference about exchange or movement. A single item does not establish every detail of a trade network.'],
['history',8,'Two medieval sources describe the same ruler differently. Which question most directly helps explain the difference?','Who created each source, for which audience and purpose?','Which source has the most attractive border?','Which source uses the shortest words?','Which account is most convenient to believe?','Authors’ positions, intended audiences and purposes shape historical representations. Context and corroboration help explain differing accounts.'],
['history',7,'Why is an archaeological context important when interpreting an artefact?','Its location and relationship to other finds can help explain its use and age.','The object’s colour alone provides every answer.','An artefact has the same meaning in every location.','Context prevents historians from using evidence.','An object’s position, surrounding materials and association with other finds can support dating and interpretation. Removing that context can lose information.'],
['history',8,'A historian links a changed farming method with population growth. What would strengthen this explanation?','Evidence about dates, food production and other possible causes.','Assuming that two changes occurring together prove causation.','Ignoring evidence that does not fit the claim.','Using only a modern fictional film.','An explanation of historical change should be tested against chronology, relevant evidence and alternative contributing factors.'],
['geography',7,'Why can urban growth increase flood risk in some catchments?','More sealed surfaces can increase rapid runoff into waterways.','Concrete always absorbs more rainfall than soil.','Buildings prevent all rain from falling.','Catchment land use cannot affect water movement.','Roads and roofs reduce infiltration compared with many vegetated surfaces. More water can run quickly into drains and streams.'],
['geography',8,'A coastal town is considering a sea wall. Which evaluation is most complete?','Assess protection, cost, habitat effects and possible erosion elsewhere.','Consider only how tall the wall looks.','Assume every coastline responds identically.','Ignore changes beyond the construction site.','Coastal interventions can create benefits and consequences at different places and times. Evaluation should consider several connected effects.'],
['civics',7,'Why does a democratic system benefit from independent scrutiny of government?','It supports accountability by examining actions and decisions.','It guarantees that every government decision is perfect.','It removes the need for elections.','It requires everyone to hold identical views.','Independent scrutiny can expose problems and inform public debate. It supports accountability without guaranteeing that all decisions will be correct.'],
['civics',8,'A proposed rule treats everyone identically but creates a barrier for people with a disability. What should decision-makers consider?','Whether adjustments are needed to provide fair participation.','Whether identical treatment always guarantees fair access.','Whether affected people should be excluded from discussion.','Whether accessibility can be ignored when it is inconvenient.','Equality of treatment does not always create equitable access. Considering people’s circumstances and reasonable adjustments supports participation.'],
['economics',7,'A family compares two phone plans. Which measure gives the fairest cost comparison?','Total cost over the same period, including fixed and usage charges.','Only the colour of the advertisement.','Only the first month when a temporary discount applies.','The number of words in each plan name.','A common comparison period and all relevant charges allow the plans to be compared on a consistent basis.'],
['economics',8,'Why does a rise in a business’s sales revenue not necessarily mean its profit rose?','Costs may have increased by more than revenue.','Revenue and profit always mean exactly the same thing.','Profit cannot depend on expenses.','A business with customers has no costs.','Profit is revenue minus costs. Higher sales can still produce lower profit if costs rise sufficiently.'],
['digital',7,'A program accepts a number and checks whether it is greater than 10. Which construct selects an action based on that test?','A conditional statement.','A comment that is never executed.','A filename extension.','A keyboard shortcut.','A conditional statement chooses between branches according to a condition, such as whether an input is greater than 10.'],
['digital',8,'Why should a program test boundary inputs such as 0, 1 and the maximum allowed value?','Boundary cases can reveal errors missed by typical inputs.','Programs only ever receive boundary inputs.','Testing replaces the need to understand the intended behaviour.','A successful test proves a program has no possible bugs.','Errors often occur at the edges of valid ranges. Boundary tests complement ordinary and invalid-input tests.'],
['design',7,'A design brief says a container must protect its contents and use little material. What is the next useful step?','Develop measurable criteria for protection and material use.','Choose a colour and ignore the brief.','Assume all designs perform identically.','Test only whether classmates like its name.','Measurable criteria turn a broad brief into requirements that can be evaluated during prototyping and testing.'],
['design',8,'A reusable product lasts longer but uses more material to manufacture. What comparison helps evaluate sustainability?','Compare impacts over its expected life, including use, repair and disposal.','Look only at its purchase price.','Assume reusable products have no environmental impacts.','Ignore how long the product lasts.','A life-cycle approach considers production, use and end-of-life impacts. Longevity and repairability can affect the overall comparison.'],
['arts',7,'How can changing a scene’s lighting from warm and bright to cold and dim affect its meaning?','It can shift the mood and guide the audience’s interpretation.','It cannot influence an audience in any way.','It proves the scene takes place in a different country.','It gives the exact age of every character.','Lighting is an expressive choice. Colour and intensity can suggest moods, while the wider context shapes the interpretation.'],
['arts',8,'A media artwork deliberately combines a cheerful soundtrack with troubling images. What effect might this create?','A contrast that prompts the audience to question the scene.','A guarantee that every viewer will react identically.','Proof that sound has no relationship to images.','A literal explanation of every image.','Contrasting expressive elements can create tension, irony or uncertainty and invite viewers to consider their relationship.'],
['music',7,'A piece changes from quiet to loud over several bars. Which instruction describes this?','Crescendo.','Decrescendo.','A rest for the entire passage.','A constant volume throughout.','A crescendo is a gradual increase in loudness. Dynamics describe loudness rather than the speed of the beat.'],
['music',8,'A melody is repeated higher while preserving its interval pattern. What musical process is this?','Transposition.','Muting every note.','Changing every interval at random.','Removing the melody’s rhythm entirely.','Transposition moves music to a different pitch level while preserving its interval relationships. The rhythm can remain the same.'],
['health',7,'A friend shares a private message without consent. Which response best supports respectful relationships?','Explain the privacy concern, ask them to stop sharing it and seek trusted support if needed.','Forward it to more people to be fair.','Assume friendship removes the need for consent.','Post a public insult in response.','Respectful relationships include boundaries, consent and privacy. A calm response and trusted support can help address harm.'],
['health',8,'Why should health claims in an advertisement be checked against independent evidence?','The seller has a commercial interest, and the claim may omit limitations.','Advertisements are always false.','An expensive product is always more effective.','Independent evidence can never change a conclusion.','Commercial interests can influence how evidence is presented. Independent evidence helps assess the claim and its limits without assuming every claim is false.'],
['sports',7,'Why can practising a skill in varied game situations improve performance?','It helps players adapt the skill to changing decisions and constraints.','It guarantees that mistakes will never happen.','It removes the need for feedback.','It makes every sport use the same rules.','Variable practice can develop decision-making and transfer, alongside focused practice and feedback. Performance still depends on the situation.'],
['sports',8,'A coach compares only the fastest players before and after a new training method. What limits the conclusion?','The selected group may not represent the whole team.','Fast players cannot improve.','Times are never useful evidence.','All players must respond identically to training.','Selecting only one subgroup can limit how widely results apply. Baseline differences and other influences also matter.'],
['languages',7,'Why might a literal translation of an idiom confuse a listener?','The expression’s conventional meaning may differ from its individual words.','Every language uses exactly the same idioms.','Idioms never carry meaning.','Translation always requires replacing only the first word.','Idioms often have meanings that depend on cultural and linguistic conventions, so word-for-word translation can lose the intended meaning.'],
['languages',8,'A speaker changes from an informal greeting to a formal one when addressing an elder. What are they adapting?','Register in response to relationship and context.','The number of languages that exist.','The physical volume of every sentence only.','The meaning of all greetings everywhere.','Register includes choices suited to social relationships, setting and purpose. Conventions differ across languages and communities.'],
['general',7,'Why is a comparison using equal units important when reading an international data table?','Different units can make similar quantities appear misleadingly different.','Units change the physical size of a country.','A larger printed number always means a larger quantity.','Converting units removes all uncertainty from data.','A fair numerical comparison requires compatible units and definitions. Units alone do not address every issue in data quality.'],
['general',8,'A headline says an event doubled from 1 case to 2 cases. Which extra information is most useful?','The absolute numbers, population size and time period.','Only the percentage increase, with all counts hidden.','The font used in the headline.','A guarantee that the same change will occur forever.','A relative change can sound large when the starting count is small. Counts, denominators and time periods provide context.'],
['social',7,'Why should an AI-generated summary be checked against reliable original sources?','It can contain confident errors or omit important context.','Every AI summary is necessarily correct.','Summaries remove the need to understand evidence.','Original sources always agree with each other.','AI output can be useful but may misstate information. Checking sources and context supports more reliable judgement.'],
['social',8,'A graph about online behaviour uses a small voluntary survey. What is the most reasonable caution?','The respondents may differ from people who did not volunteer.','A small survey proves the opposite of every result.','Voluntary surveys always represent everyone perfectly.','Graphs cannot communicate survey results.','Self-selection can introduce bias. The results describe respondents and need care before being generalised to a wider population.']
];
for(const[id,year,prompt,a,b,c,d,why]of SECONDARY_CONCEPTS)secondaryQuestion(id,year,prompt,[a,b,c,d],why);
const formatNumber=n=>String(Math.round(n*10000)/10000);
function numericSecondary(id,year,prompt,answer,why,family,unit='',tier=year===7?(['linear-one-side','mass-portions','tile-linear'].includes(family)?5:4):(['linear-both-sides','linked-numbers','binary-patterns'].includes(family)?8:['quadratic-substitution','simple-interest','energy-efficiency'].includes(family)?7:6)){const n=Number(answer),values=[n,n+1,n-1,n+3].map(v=>formatNumber(v)+unit);secondaryQuestion(id,year,prompt,values,why,family,tier)}
// Different operations and data values provide fresh practice, not a live question-generation service.
let secondarySerial=0;
while(Object.values(BANK).reduce((n,a)=>n+a.length,0)<2000){
 const i=secondarySerial++,variant=i%24,k=Math.floor(i/24),year=variant%2?8:7,a=3+k,b=2+k%9,c=5+k%7;
 if(variant===0)numericSecondary('maths',7,`Solve ${b}x + ${c} = ${b*a+c}. What is x?`,a,`Subtract ${c} from both sides, then divide by ${b}. This gives x = ${a}.`,'linear-one-side');
 if(variant===1){const x=k-15,p=2+k%5,q=p+2,r=7+k%9,s=r-(q-p)*x;numericSecondary('maths',8,`Solve ${p}x + ${r} = ${q}x + (${s}). What is x?`,x,`Subtract ${p}x from both sides, then subtract ${s}: ${r-s} = ${q-p}x. Divide by ${q-p} to get x = ${x}.`,'linear-both-sides')}
 if(variant===2)numericSecondary('science',7,`A sample has mass ${a*10} g and is split into ${b} equal portions. What is the mass of each portion, in grams (round to four decimal places if needed)?`,a*10/b,`Equal portions divide the mass: ${a*10} ÷ ${b} = ${formatNumber(a*10/b)} g (rounded to four decimal places).`,'mass-portions');
 if(variant===3){const mass=(k+6)*b,volume=b;numericSecondary('science',8,`A block has mass ${mass} g and volume ${volume} cm³. Using density = mass ÷ volume, what is its density in g/cm³?`,mass/volume,`Density compares mass with volume: ${mass} ÷ ${volume} = ${mass/volume} g/cm³.`,'density')}
 if(variant===4){const distance=(k+1)*5,scale=50000;numericSecondary('geography',7,`On a 1:${scale} map, a route measures ${distance} cm. How many kilometres does it represent?`,distance*.5,`Each centimetre represents 50,000 cm = 0.5 km. Multiply ${distance} by 0.5 to get ${distance*.5} km.`,'map-scale')}
 if(variant===5){const pop=(k+20)*120,area=12;numericSecondary('geography',8,`A district has ${pop} residents in ${area} km². What is its population density, in people per km²?`,pop/area,`Divide population by area: ${pop} ÷ ${area} = ${pop/area} people per square kilometre.`,'population-density')}
 if(variant===6){const revenue=(k+10)*15,cost=(k+5)*10;numericSecondary('economics',7,`A market stall takes $${revenue} in sales and pays $${cost} in costs. What is its profit, in dollars?`,revenue-cost,`Profit is revenue minus costs: ${revenue} − ${cost} = $${revenue-cost}.`,'profit')}
 if(variant===7){const principal=(k+2)*100,rate=5,years=3;numericSecondary('economics',8,`A hypothetical savings example uses simple interest: $${principal} at ${rate}% a year for ${years} years. How many dollars of interest are earned?`,principal*.05*years,`Simple interest = principal × rate × time = ${principal} × 0.05 × 3 = $${principal*.05*years}. This is a calculation example, not a product offer.`,'simple-interest')}
 if(variant===8){const bars=k+4;numericSecondary('music',7,`A 3/4 passage contains ${bars} complete bars. How many crotchet beats are there altogether?`,bars*3,`In 3/4 time there are three crotchet beats per bar. ${bars} × 3 = ${bars*3} beats.`,'triple-time')}
 if(variant===9){const bars=k+3;numericSecondary('music',8,`A 6/8 passage contains ${bars} complete bars. How many quavers fill the passage?`,bars*6,`Each bar contains six quavers. ${bars} × 6 = ${bars*6}. Grouping those quavers into two compound beats does not change the quaver count.`,'compound-time')}
 if(variant===10){const start=k-20,change=8;numericSecondary('maths',7,`The temperature is ${start}°C and falls by ${change}°C. What is the new temperature in °C?`,start-change,`A fall subtracts from the signed temperature: ${start} − ${change} = ${start-change}°C.`,'integer-change')}
 if(variant===11){const x=k-8;numericSecondary('maths',8,`Evaluate 3x² − 2x when x = ${x}.`,3*x*x-2*x,`Square ${x}, multiply by 3, then subtract 2 × (${x}). The result is ${3*x*x-2*x}.`,'quadratic-substitution')}
 if(variant===12){const start=k+5,step=b;numericSecondary('logic',7,`A growing tile pattern starts at ${start} tiles and gains ${step} tiles per stage. How many tiles are in stage 9 if the start is stage 1?`,start+8*step,`Stage 9 is eight increases after stage 1: ${start} + 8 × ${step} = ${start+8*step}.`,'tile-linear')}
 if(variant===13){const x=k+4,y=x*2+3;numericSecondary('logic',8,`Two numbers total ${x+y}. The larger is 3 more than twice the smaller. What is the smaller number?`,x,`Let the smaller be n. Then n + 2n + 3 = ${x+y}; 3n = ${x+y-3}, so n = ${x}.`,'linked-numbers')}
 if(variant===14){const laps=k+4,seconds=45;numericSecondary('sports',7,`A runner completes ${laps} laps at a constant 45 seconds per lap. How many seconds do the laps take?`,laps*seconds,`At a constant rate, total time = laps × time per lap: ${laps} × 45 = ${laps*45} seconds.`,'lap-time')}
 if(variant===15){const old=k+20,newTime=old*.8;numericSecondary('sports',8,`A sprint time falls from ${old} seconds to ${formatNumber(newTime)} seconds. By how many seconds did the time decrease?`,old-newTime,`Subtract the new time from the original: ${old} − ${formatNumber(newTime)} = ${formatNumber(old-newTime)} seconds. A lower time represents a faster sprint over the same distance.`,'time-improvement')}
 if(variant===16){const files=k+10,size=8;numericSecondary('digital',7,`Each data record uses 8 bytes. Ignoring overhead, how many bytes do ${files} records use?`,files*size,`For equal-sized records, storage = record count × bytes per record: ${files} × 8 = ${files*8} bytes.`,'data-records')}
 if(variant===17){const bits=3+k%7,copies=1+Math.floor(k/7);numericSecondary('digital',8,`A ${bits}-bit code has 2^${bits} possible patterns. If each pattern is stored ${copies} times, how many records are stored?`,2**bits*copies,`There are 2^${bits} = ${2**bits} distinct bit patterns. Storing each ${copies} times gives ${2**bits*copies} records.`,'binary-patterns')}
 if(variant===18){const l=k+5,w=b;numericSecondary('design',7,`A rectangular model panel is ${l} cm by ${w} cm. What is its perimeter in centimetres?`,2*(l+w),`Perimeter adds all four sides: 2 × (${l} + ${w}) = ${2*(l+w)} cm.`,'panel-perimeter')}
 if(variant===19){const factor=2+k%4,length=k+8;numericSecondary('design',8,`A scale model has a length of ${length} cm. Every linear dimension is enlarged by a factor of ${factor}. What is the new length in centimetres?`,length*factor,`A linear scale factor multiplies length: ${length} × ${factor} = ${length*factor} cm. Area would scale by the square of the factor.`,'linear-scale')}
 if(variant===20){const plants=k+7,rate=b;numericSecondary('biology',7,`A simplified field model assumes ${plants} plants each support ${rate} insects. How many insects does the model predict?`,plants*rate,`Apply the stated model: ${plants} × ${rate} = ${plants*rate} insects. Real ecosystems vary; this is a model prediction rather than an exact ecological rule.`,'ecology-model')}
 if(variant===21){const energy=(k+10)*100,percent=20;numericSecondary('science',8,`A device receives ${energy} J of energy and transfers 20% into useful movement. How many joules become useful movement?`,energy*.2,`Useful output = input × efficiency: ${energy} × 0.20 = ${energy*.2} J. The rest is transferred in other forms.`,'energy-efficiency')}
 if(variant===22){const total=(k+4)*12,sample=total/3;numericSecondary('social',7,`A survey has ${total} respondents and ${sample} choose public transport. How many respondents choose something else?`,total-sample,`The other responses total ${total} − ${sample} = ${total-sample}. These counts describe the respondents, not necessarily the whole community.`,'survey-count')}
 if(variant===23){const angle=15+k;numericSecondary('maths',8,`A triangle has angles of ${angle}° and ${angle+20}°. What is the third angle in degrees?`,180-angle-(angle+20),`Angles in a triangle total 180°. Subtract ${angle} and ${angle+20}: 180 − ${angle} − ${angle+20} = ${180-angle-(angle+20)}°.`,'triangle-deduction')}
}
QUESTION_COUNT=Object.values(BANK).reduce((n,a)=>n+a.length,0);
QUESTION_STAGES.splice(0,QUESTION_STAGES.length,{level:1,tier:1,year:6,name:'Year 6 · Foundation'},{level:5,tier:2,year:6,name:'Year 6 · Explorer'},{level:10,tier:3,year:6,name:'Year 6 · Problem solver'},{level:18,tier:4,year:7,name:'Year 7 · Strategist'},{level:26,tier:5,year:7,name:'Year 7 · Master reasoning'},{level:35,tier:6,year:8,name:'Year 8 · Explorer'},{level:42,tier:7,year:8,name:'Year 8 · Advanced reasoning'},{level:50,tier:8,year:8,name:'Year 8 · Cosmic mastery'});
// Never give a later-year question in an earlier-year round. Prefer unseen items near the current stage.
buildQuestionDeck=function(subject){const stage=questionStage(),all=ungradedDeck(subject),eligible=all.filter(item=>(item.q[8]||6)<=stage.year),fresh=eligible.filter(item=>!profile.questionSeen[questionKey(item)]),seen=eligible.filter(item=>profile.questionSeen[questionKey(item)]);const rank=item=>Math.abs(itemDifficulty(item)-stage.tier)+(itemDifficulty(item)>stage.tier?1:0)+(stage.year-(item.q[8]||6))*3;return [...fresh.map((item,i)=>({item,i,cost:rank(item)})).sort((a,b)=>a.cost-b.cost||a.i-b.i).map(x=>x.item),...seen]};
